// Replays Shared/Definitions/conformance/movement_vectors.txt (generated by the
// Rust implementation) and requires bit-identical results.
#include "TestFramework.h"
#include "NetCore/TfpsMap.h"
#include "NetCore/TfpsMovement.h"
#include "NetCore/TfpsWeapon.h"

#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>

namespace
{
	std::string ReadFile(const std::string& Path)
	{
		std::ifstream F(Path, std::ios::binary);
		std::stringstream SS;
		SS << F.rdbuf();
		return SS.str();
	}

	float Hex(const std::string& S) { return tfps::BitsToFloat(static_cast<uint32_t>(std::strtoul(S.c_str(), nullptr, 16))); }
	float NextHex(std::istringstream& In) { std::string X; In >> X; return Hex(X); }
	unsigned long NextU(std::istringstream& In) { unsigned long V = 0; In >> V; return V; }

	void ReadMove(std::istringstream& In, tfps::MoveState& S)
	{
		S.Pos.X = NextHex(In); S.Pos.Y = NextHex(In); S.Pos.Z = NextHex(In);
		S.Vel.X = NextHex(In); S.Vel.Y = NextHex(In); S.Vel.Z = NextHex(In);
		S.bOnGround = NextU(In) != 0; S.bCrouched = NextU(In) != 0; S.bProne = NextU(In) != 0;
		S.JumpTimer = NextHex(In); S.StanceTimer = NextHex(In); S.Lean = NextHex(In); S.Aim = NextHex(In);
	}

	void ReadWeapon(std::istringstream& In, tfps::WeaponState& W)
	{
		W.Active = static_cast<uint8_t>(NextU(In));
		for (auto& Sl : W.Slots)
		{
			Sl.Ammo = static_cast<uint16_t>(NextU(In)); Sl.bChambered = NextU(In) != 0; Sl.Reserve = static_cast<uint16_t>(NextU(In));
		}
		W.Cooldown = NextHex(In); W.ReloadTimer = NextHex(In); W.bReloadEmpty = NextU(In) != 0; W.EquipTimer = NextHex(In);
		W.BurstLeft = static_cast<uint8_t>(NextU(In)); W.bTriggerPrev = NextU(In) != 0; W.ShotsFired = static_cast<uint16_t>(NextU(In));
		W.RecoilPitch = NextHex(In); W.RecoilYaw = NextHex(In); W.RecoverTimer = NextHex(In);
		W.ShotCounter = static_cast<uint32_t>(NextU(In));
	}

	tfps::WeaponSet LoadWeapons()
	{
		tfps::WeaponSet Set;
		std::string Err;
		tfps::ParseWeaponsJson(ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/weapons.json"), Set, Err);
		return Set;
	}
}

TFPS_TEST(PlayerSimConformanceWithRust)
{
	const std::string Text = ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/conformance/player_vectors.txt");
	TFPS_REQUIRE(!Text.empty());
	const tfps::WeaponSet Weapons = LoadWeapons();
	TFPS_REQUIRE(Weapons.Weapons.size() == 5);
	std::istringstream Lines(Text);
	std::string Line;
	std::getline(Lines, Line);
	TFPS_REQUIRE(Line == "tfps-player-vectors 4");
	tfps::CollisionWorld World;
	tfps::MoveState Ms;
	tfps::WeaponState Ws;
	const tfps::WeaponDef* Loadout[tfps::kWeaponSlots] = {nullptr, nullptr};
	tfps::ShotBuffer Shots;
	float Dt = 0.0f;
	std::string SeqName;
	int Steps = 0, Mismatches = 0, Sequences = 0, ShotsChecked = 0, DestroyedCells = 0;
	while (std::getline(Lines, Line))
	{
		std::istringstream In(Line);
		std::string Kind;
		In >> Kind;
		if (Kind == "solid")
		{
			tfps::Aabb B;
			B.Min.X = NextHex(In); B.Min.Y = NextHex(In); B.Min.Z = NextHex(In);
			B.Max.X = NextHex(In); B.Max.Y = NextHex(In); B.Max.Z = NextHex(In);
			const auto Mat = static_cast<tfps::EMaterial>(NextU(In));
			const bool bDestructible = NextU(In) != 0;
			World.PushSolid(B, Mat, bDestructible);
		}
		else if (Kind == "destroyed")
		{
			const uint32_t Cell = static_cast<uint32_t>(NextU(In));
			if (!World.DestroyCell(Cell)) { ++Mismatches; }
			++DestroyedCells;
		}
		else if (Kind == "seq")
		{
			In >> SeqName;
			Dt = NextHex(In);
			Loadout[0] = Weapons.Get(static_cast<uint8_t>(NextU(In)));
			Loadout[1] = Weapons.Get(static_cast<uint8_t>(NextU(In)));
			++Sequences;
		}
		else if (Kind == "start")
		{
			ReadMove(In, Ms);
			ReadWeapon(In, Ws);
		}
		else if (Kind == "step")
		{
			tfps::MoveInput Input;
			Input.Buttons = static_cast<uint16_t>(NextU(In));
			Input.YawQ = static_cast<uint16_t>(NextU(In));
			long P = 0;
			In >> P;
			Input.PitchQ = static_cast<int16_t>(P);
			Input.Slot = static_cast<uint8_t>(NextU(In));
			tfps::MoveState EMs;
			tfps::WeaponState EWs;
			ReadMove(In, EMs);
			ReadWeapon(In, EWs);
			const int ENShots = static_cast<int>(NextU(In));
			Shots.Clear();
			tfps::SimulatePlayer(Ms, Ws, Input, Dt, World, Loadout, Shots);
			++Steps;
			bool bOk = Ms == EMs && Ws == EWs && Shots.Len == ENShots;
			for (int I = 0; bOk && I < ENShots; ++I)
			{
				const tfps::Shot& S = Shots.Shots[I];
				const float OX = NextHex(In), OY = NextHex(In), OZ = NextHex(In), Yaw = NextHex(In), Pitch = NextHex(In);
				const unsigned long Wid = NextU(In), Pel = NextU(In), Ctr = NextU(In);
				bOk = S.Origin == tfps::Vec3(OX, OY, OZ) && S.YawDeg == Yaw && S.PitchDeg == Pitch && S.WeaponId == Wid && S.Pellet == Pel && S.ShotCounter == Ctr;
				++ShotsChecked;
			}
			if (!bOk)
			{
				if (Mismatches < 5)
				{
					std::fprintf(stderr, "  mismatch in %s step %d: pos (%.9g %.9g %.9g) vs (%.9g %.9g %.9g), shots %d vs %d, ammo %u vs %u\n", SeqName.c_str(), Steps,
						Ms.Pos.X, Ms.Pos.Y, Ms.Pos.Z, EMs.Pos.X, EMs.Pos.Y, EMs.Pos.Z, Shots.Len, ENShots, Ws.Slots[Ws.Active].Ammo, EWs.Slots[EWs.Active].Ammo);
				}
				++Mismatches;
				Ms = EMs;
				Ws = EWs;
			}
		}
	}
	std::printf("  %zu solids, %u cells (%d destroyed), %d sequences, %d steps, %d shots, %d mismatches\n", World.Solids.size(), World.CellCount,
		DestroyedCells, Sequences, Steps, ShotsChecked, Mismatches);
	// The same map parsed by C++ must subdivide into the same cells.
	tfps::MapDef Arena;
	std::string Err;
	TFPS_REQUIRE(tfps::ParseMapJson(ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/maps/test_arena.json"), Arena, Err));
	const tfps::CollisionWorld FromMap = tfps::CollisionWorld::FromMap(Arena);
	TFPS_EXPECT(FromMap.CellCount == World.CellCount);
	TFPS_EXPECT(DestroyedCells > 100);
	TFPS_EXPECT(Sequences == 18);
	TFPS_EXPECT(Steps > 10000);
	TFPS_EXPECT(ShotsChecked > 100);
	TFPS_EXPECT(Mismatches == 0);
}

TFPS_TEST(WeaponsJsonHashMatchesRust)
{
	const tfps::WeaponSet Weapons = LoadWeapons();
	std::printf("  %zu weapons, hash %016llx\n", Weapons.Weapons.size(), static_cast<unsigned long long>(Weapons.Hash()));
	const char* Expected = std::getenv("TFPS_EXPECTED_WEAPONS_HASH");
	if (Expected != nullptr)
	{
		TFPS_EXPECT(std::strtoull(Expected, nullptr, 16) == Weapons.Hash());
	}
	TFPS_EXPECT(Weapons.Weapons.size() == 5);
}

TFPS_TEST(MapJsonHashMatchesRust)
{
	const std::string Text = ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/maps/test_arena.json");
	tfps::MapDef Map;
	std::string Err;
	TFPS_REQUIRE(tfps::ParseMapJson(Text, Map, Err));
	// Value printed by the Rust server at startup ("map_hash=...").
	const char* Expected = std::getenv("TFPS_EXPECTED_MAP_HASH");
	std::printf("  map %s: %zu solids, hash %016llx\n", Map.Name.c_str(), Map.Solids.size(), static_cast<unsigned long long>(Map.GeometryHash()));
	if (Expected != nullptr)
	{
		TFPS_EXPECT(std::strtoull(Expected, nullptr, 16) == Map.GeometryHash());
	}
	TFPS_EXPECT(Map.Solids.size() == 105);
	TFPS_EXPECT(Map.Spawns.size() == 6);
}

#include "NetCore/TfpsDeterminism.h"

TFPS_TEST(DeterminismSelfTestMatchesRust)
{
	const uint64_t H = tfps::DeterminismSelfTestHash();
	std::printf("  self-test hash %016llx (expected %016llx)\n", static_cast<unsigned long long>(H), static_cast<unsigned long long>(tfps::kExpectedSelfTestHash));
	TFPS_EXPECT(tfps::DeterminismSelfTestPasses());
}
